{
  "name": "PI C-867双轴压电定位台",
  "name_en": "PI C-867 Two-Axis Piezo Positioning Stage",
  "manufacturer": "Physik Instrumente (PI)",
  "description": "用于控制PI C-867相关的双轴压电/纳米定位平台，可进行XY位置读取、绝对与相对移动、速度设置、伺服开关和参考初始化，常用于显微成像中的精密扫描、样品对准和纳米级定位。",
  "description_en": "A PI C-867-based two-axis piezo/nanopositioning stage used for XY position readout, absolute and relative motion, velocity setting, servo control, and reference initialization. It is typically used for precision scanning, sample alignment, and nanometer-scale positioning in microscopy.",
  "actions": [
    {
      "action_name": "auto-SetServo",
      "description": "启用或关闭定位台的伺服闭环控制。",
      "description_en": "Enable or disable the stage's closed-loop servo control."
    },
    {
      "action_name": "auto-ReInit",
      "description": "重新初始化控制器，并可选择执行参考点/参考开关校准。",
      "description_en": "Reinitialize the controller and optionally perform reference-point/reference-switch calibration."
    },
    {
      "action_name": "auto-SetVelocity",
      "description": "设置指定通道的移动速度。",
      "description_en": "Set the motion velocity for the specified channel."
    },
    {
      "action_name": "auto-GetVelocity",
      "description": "查询指定通道的移动速度。",
      "description_en": "Query the motion velocity of the specified channel."
    },
    {
      "action_name": "auto-MoveTo",
      "description": "将指定通道移动到绝对目标位置。",
      "description_en": "Move the specified channel to an absolute target position."
    },
    {
      "action_name": "auto-MoveRel",
      "description": "使指定通道按给定增量做相对移动。",
      "description_en": "Move the specified channel by a relative increment."
    },
    {
      "action_name": "auto-MoveToXY",
      "description": "同时将X、Y两个通道移动到目标位置。",
      "description_en": "Move the X and Y channels to their target positions together."
    },
    {
      "action_name": "auto-GetPos",
      "description": "读取指定通道的当前位置。",
      "description_en": "Read the current position of the specified channel."
    },
    {
      "action_name": "auto-GetPosXY",
      "description": "读取X、Y两个通道的当前位置。",
      "description_en": "Read the current positions of the X and Y channels."
    },
    {
      "action_name": "auto-GetControlReady",
      "description": "查询控制器是否已准备好接受运动控制命令。",
      "description_en": "Query whether the controller is ready to accept motion-control commands."
    },
    {
      "action_name": "auto-GetChannelObject",
      "description": "查询指定通道的对象/通道信息。",
      "description_en": "Query the object or channel information associated with the specified channel."
    },
    {
      "action_name": "auto-GetChannelPhase",
      "description": "查询指定通道的相位或阶段状态信息。",
      "description_en": "Query phase or stage-status information for the specified channel."
    },
    {
      "action_name": "auto-GetMin",
      "description": "查询指定通道允许的最小位置。",
      "description_en": "Query the minimum allowed position for the specified channel."
    },
    {
      "action_name": "auto-GetMax",
      "description": "查询指定通道允许的最大位置。",
      "description_en": "Query the maximum allowed position for the specified channel."
    },
    {
      "action_name": "auto-GetFirmwareVersion",
      "description": "查询控制器固件版本。",
      "description_en": "Query the controller firmware version."
    }
  ],
  "tag_hints": [
    "piezo nanopositioning",
    "XY stage control",
    "closed-loop servo",
    "microscope scanning",
    "absolute and relative motion",
    "serial motion controller",
    "precision sample alignment"
  ]
}

